				useProxy(t, fwd)
				got := tc.build()

				if want := withNamesBeforeImage(t, plain.Args, netproxy.ForwardedVariables); !slices.Equal(got.Args, want) {
					t.Errorf("Args =\n  %q\nwant\n  %q", got.Args, want)
				}
